"""Root-only Source preparation; scientific inputs remain current7-only here."""
import ast,json,os
from pathlib import Path
import temperature_capture_helpers as h

def main():
 b=h.BASE;h.require(not any((b/n).exists() for n in ('PLAN.json','SOURCE_REVIEW_READY.json','actual_temperature_operand_capture')),'fresh once preparation/output')
 ap=h.meta_pin(b/'AUTHOR_SOURCE_ONLY_FREEZE.json');author=h.read(ap);seedpin=h.meta_pin(b/'METADATA_SOURCE_SEED.json');seed=h.read(seedpin)
 h.require(author['source_only'] is True and author['source_preparation_executed'] is False and author['stop_writes_after_freeze'] is True,'author frozen Source only')
 for p in author['source_pins']:h.require(h.meta_pin(p['path'])==p,'whole frozen Source');ast.parse(h.exact(p))
 full=h.read(seed['inherited_full_operator_plan_pin']);roots=full['complete_joint_roots'];h.require(full['original_caps']==h.CAPS and len(roots)==len(set(roots))==56 and str(b.parent) in roots and not any(Path(x).is_relative_to(Path(y)) for x in roots for y in roots if x!=y),'exact inherited56 whole TOP already counted, original caps')
 req=h.read(seed['aggregate_request_pin']);ctx=h.read(seed['fixed_context_pin']);ext=h.read(seed['original_final55_extraction_report_pin']);post=h.read(seed['original_extraction_post_pin']);primary=h.read(seed['original_extraction_post_primary_pin']);tools=h.read(seed['original_extraction_post_tools_pin']);root=h.read(seed['original_extraction_Root_tools_pin']);host=h.read(seed['original_extraction_Host_pin'])
 pair=req['aggregation_binding']['states']['A'];h.require(pair['sqlite_pin']==seed['original_SQLite_pin']==full['observed_final55_SQLite_pin'] and pair['native_pool_pin']==seed['original_pool_pin']==full['observed_final55_pool_pin'],'same exact final55 original SQL/pool provenance')
 h.require(post['status']=='PASS_ACTUAL_CURRENT_MATERIAL_EXTRACTION_SAVED_OUTPUT_AND_INPUT_PIN_COVERAGE' and post['failure'] is None and post['actual_child_integer_exit_code']==2 and post['actual_Root_true_tool_return_pin']==seed['original_extraction_Root_tools_pin'] and post['actual_extraction_report_pin']==seed['original_final55_extraction_report_pin'] and post['actual_extraction_host_pin']==seed['original_extraction_Host_pin'],'original extraction post0 and intentional child2 provenance')
 h.closed0(tools,'actual_review_return',seed['original_extraction_post_primary_pin'],'review_pin');h.require(json.loads(tools['actual_review_return']['output'])['actual_extraction_review_pin']==seed['original_extraction_post_pin'],'same genuine dual post output')
 t=root['actual_terminal_return'];h.require(root['observed_closed'] is True and type(root['original_integer_exit_code']) is int and root['original_integer_exit_code']==0 and type(t['exit_code']) is int and t['exit_code']==0 and t.get('session_id') is None and host['status']=='ACTUAL_COMPLETE_CURRENT_EVIDENCE_EXIT2_CLOSED_ONLY' and ext['status']=='ACTUAL_CURRENT_COMPLETE_CONTEXT_AND_RAW_SNAPSHOT_EVIDENCE_ONLY_EXIT2','original owning Root0 with intentional evidence child2, no numerical qualification')
 for p in (seed['original_SQLite_pin'],seed['original_pool_pin'],seed['original_final55_input_pin'],seed['logical_inventory_current7_pin']):h.current(p)
 h.require(len(seed['selected_original_records'])==4 and sum(r['native_payload_end_byte']-r['native_payload_begin_byte'] for r in seed['selected_original_records'])==1984,'exact four selected descriptors/1984B')
 for r in seed['selected_original_records']:h.require(ctx['original_context_records'][h.path_key(r['path'])]['original_record']==r,'exact fixed-context original descriptor')
 case=h.read(seed['current_case_spec_pin']);h.require(case['geometry']['region_order_outer_to_inner']==seed['expected_original_region_order'] and case['materials']['temperature_C_in_every_zone']==full['current_case_temperature_C'] and case['materials']['kelvin_offset']==full['current_case_kelvin_offset'],'original current parameter C/K inputs and mix geometry order')
 pins=author['source_pins']+[ap,seedpin]+[seed[k] for k in ('aggregate_request_pin','fixed_context_pin','inherited_full_operator_plan_pin','original_saved_native_adapter_Source_pin','original_extraction_post_pin','original_extraction_post_primary_pin','original_extraction_post_tools_pin','original_extraction_Root_tools_pin','original_extraction_Host_pin','original_final55_extraction_report_pin','current_case_spec_pin')]
 plan=dict(schema='CURRENT_62SLOT_TEMPERATURE_OPERAND_CAPTURE_SOURCE_PLAN_V1',source_only=True,seed_pin=seedpin,author_source_freeze_pin=ap,source_pins=author['source_pins'],metadata_pins=pins,complete_joint_roots=roots,original_caps=h.CAPS,inherited_full_operator_plan_pin=seed['inherited_full_operator_plan_pin'],inherited_explicit_metadata_pins=full['explicit_cumulative_metadata_file_pins'],original_support_Source_pin=full['original_support_Source_pin'],original_Common_Source_pin=full['original_Common_Source_pin'],original_bounded_Source_pin=full['original_bounded_Source_pin'],output_directory=str(b/'actual_temperature_operand_capture'),scientific_input_current7_pins=[seed['original_SQLite_pin'],seed['original_pool_pin']],original_final55_XSM_current7_pin=seed['original_final55_input_pin'],logical_inventory_current7_pin=seed['logical_inventory_current7_pin'],current_case_spec_pin=seed['current_case_spec_pin'],selected_original_records=seed['selected_original_records'],expected_C_by_mix=seed['expected_C_by_mix'],expected_original_region_order=seed['expected_original_region_order'],business_executed=False,numerical_executed=False,compiler_executed=False,files_deleted=False,**h.FALSE)
 pp=h.write(b/'PLAN.json',plan);ready=h.write(b/'SOURCE_REVIEW_READY.json',dict(schema='CURRENT_62SLOT_TEMPERATURE_OPERAND_SOURCE_READY_V1',source_only=True,plan_pin=pp,author_source_freeze_pin=ap,selected_Source_and_metadata_pins=pins,business_executed=False,numerical_executed=False,compiler_executed=False,files_deleted=False,**h.FALSE));print(json.dumps(dict(status='TEMPERATURE_OPERAND_SOURCE_PREPARED_ONLY',ready_pin=ready,**h.FALSE)),flush=True)
if __name__=='__main__':main()
